_NAME = ".packignore"


def _compile(pattern):
    """Translate a cleaned-up pattern into a regex for a relative path."""
    parts = []
    for seg in pattern.split("/"):
        if not (seg == "**" and parts and parts[-1] == "**"):
            parts.append(seg)
    out = []
    for i, seg in enumerate(parts):
        if seg == "**":
            if len(parts) == 1:
                out.append(".*")
            elif i == 0:
                out.append("(?:.*/)?")
            else:
                out.append("(?:/.*)?")
            continue
        if i > 0 and not (i == 1 and parts[0] == "**"):
            out.append("/")
        for tok in re.findall(r"\*+|\?|[^*?]+", seg):
            if tok[0] == "*":
                out.append("[^/]*")
            elif tok == "?":
                out.append("[^/]")
            else:
                out.append(re.escape(tok))
    return "".join(out)


def _parse(text):
    """Return the rules in a .packignore file as (negate, dir_only, score, regex)."""
    rules = []
    for line in text.splitlines():
        s = line.strip()
        if not s or s.startswith(";"):
            continue
        negate = s.startswith("!")
        if negate:
            s = s[1:]
        dir_only = s.endswith("/")
        s = s.rstrip("/")
        anchored = "/" in s
        s = s.lstrip("/")
        if not s:
            continue
        regex = _compile(s)
        if not anchored:
            regex = "(?:.*/)?" + regex
        score = sum(c not in "*?/" for c in s)
        rules.append((negate, dir_only, score, re.compile(regex, re.DOTALL)))
    return rules


def _files(root):
    """Yield every regular file under `root` as a "/"-separated relative path."""
    for dirpath, dirnames, filenames in os.walk(root):
        if os.path.samefile(dirpath, root) and ".git" in dirnames:
            dirnames.remove(".git")

